node -e "
const db = require('better-sqlite3')('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log(t.name + ':', cols.map(c => c.name + ' (' + c.type + ')').join(', '));
  const count = db.prepare('SELECT COUNT(*) as n FROM ' + t.name).get();
  console.log('  rows:', count.n);
}
"

node -e "
const db = require('better-sqlite3')('/workspace/world.db');
const row = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-FA0948'\").get();
if (row) {
  for (const [k, v] of Object.entries(row)) {
    console.log(k + ':', v);
  }
} else {
  console.log('Not found. Searching for partial match...');
  const rows = db.prepare(\"SELECT product_id, name FROM products WHERE product_id LIKE '%FA0948%' OR name LIKE '%wireless%mouse%'\").all();
  rows.forEach(r => console.log(r.product_id, '-', r.name));
}
"
